import functools

def retry(times=3, exceptions=(Exception,)):
    def deco(fn):
        @functools.wraps(fn)
        def wrapper(*a, **kw):
            last = None
            for attempt in range(1, times + 1):
                try:
                    return fn(*a, **kw)
                except exceptions as e:
                    last = e
                    print(f"attempt {attempt} failed: {e}")
            raise last
        return wrapper
    return deco

calls = {"n": 0}

@retry(times=3, exceptions=(ConnectionError,))
def flaky():
    """Fetch data."""
    calls["n"] += 1
    if calls["n"] < 3:
        raise ConnectionError(f"down {calls['n']}")
    return "ok"

