from contextlib import contextmanager, suppress

class Res:
    def __init__(self, name):
        self.name = name
    def __enter__(self):
        print("open", self.name)
        return self
    def __exit__(self, et, ev, tb):
        print("close", self.name, et.__name__ if et else None)
        return False

@contextmanager
def swallow(*exc):
    try:
        yield
    except exc as e:
        print("swallowed", type(e).__name__)

with Res("a"), Res("b"):
    print("body")

with swallow(KeyError):
    {}["x"]

with suppress(ZeroDivisionError):
    1 / 0

try:
    with Res("c"):
        raise ValueError
except ValueError:
    print("propagated")

from functools import lru_cache

calls = 0

@lru_cache(maxsize=None)
def fib(n):
    global calls
    calls += 1
    return n if n < 2 else fib(n - 1) + fib(n - 2)

print(fib(30), calls)
print(fib.cache_info())
fib.cache_clear()

