import io
import unittest

def slugify(s):
    return "-".join(s.lower().split())

class T(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(slugify("Hello World"), "hello-world")

    def test_spaces(self):
        self.assertEqual(slugify("  a   b "), "a-b")

    def test_table(self):
        for s, exp in [("A B", "a-b"), ("x", "x"), ("", "")]:
            with self.subTest(s=s):
                self.assertEqual(slugify(s), exp)

    def test_none(self):
        with self.assertRaises(AttributeError):
            slugify(None)

suite = unittest.defaultTestLoader.loadTestsFromTestCase(T)
res = unittest.TextTestRunner(stream=io.StringIO()).run(suite)
print(res.testsRun, res.wasSuccessful(), len(res.failures))

from unittest import mock

class Client:
    def get(self, url):
        raise RuntimeError("network")

def fetch_title(client, url):
    r = client.get(url)
    return r["title"].upper()

c = mock.Mock()
c.get.return_value = {"title": "hi"}
print(fetch_title(c, "http://x"))
c.get.assert_called_once_with("http://x")

c.get.side_effect = [TimeoutError("t"), {"title": "ok"}]
try:
    fetch_title(c, "u")
except TimeoutError:
    print("timeout")
print(fetch_title(c, "u"))

with mock.patch.object(Client, "get", return_value={"title": "patched"}):
    print(fetch_title(Client(), "u"))
try:
    Client().get("u")
except RuntimeError:
    print("restored")

m = mock.create_autospec(Client, instance=True)
try:
    m.gett("u")
except AttributeError:
